from math import pi


def qft_6():
    """Return a 6-qubit QFT circuit with measurement key='result'."""
    qubits = cirq.LineQubit.range(6)
    circuit = cirq.Circuit()

    for target in range(6):
        circuit.append(cirq.H(qubits[target]))
        for control in range(target + 1, 6):
            angle = pi / (2 ** (control - target))
            circuit.append(
                cirq.CZPowGate(exponent=angle / pi).on(
                    qubits[control], qubits[target]
                )
            )

    circuit.append(
        cirq.SWAP(qubits[i], qubits[5 - i]) for i in range(3)
    )
    circuit.append(cirq.measure(*qubits, key="result"))
    return circuit

