def Deutsch_Jozsa_Balance_4():
    inputs = cirq.LineQubit.range(4)
    ancilla = cirq.LineQubit(4)
    bitstring = "1100"

    circuit = cirq.Circuit(
        cirq.X(ancilla),
        cirq.H.on_each(*inputs, ancilla),
    )

    for qubit, bit in zip(inputs, bitstring):
        if bit == "1":
            circuit.append(cirq.X(qubit))

    circuit.append(cirq.CNOT(qubit, ancilla) for qubit in inputs)

    for qubit, bit in zip(inputs, bitstring):
        if bit == "1":
            circuit.append(cirq.X(qubit))

    circuit.append(cirq.H.on_each(*inputs))
    circuit.append(cirq.measure(*inputs, key="result"))
    return circuit

