def quantum_state_preparation(parameters=None):
    """
    Prepares a single-qubit state using RX and RY rotations, then measures
    the qubit with key='result'.
    """
    if parameters is None:
        parameters = (0.0, 0.0)
    if len(parameters) != 2:
        raise ValueError("parameters must contain two rotation angles.")

    qubit = cirq.LineQubit(0)
    return cirq.Circuit(
        cirq.rx(parameters[0])(qubit),
        cirq.ry(parameters[1])(qubit),
        cirq.measure(qubit, key="result"),
    )

import pennylane as qml

def grover_search_oracle_00():
    """
    Use Grover's algorithm to find |00>, returning 1000 samples.
    """
    dev = qml.device("default.qubit", wires=2, shots=1000)

    @qml.qnode(dev)
    def circuit():
        for wire in range(2):
            qml.Hadamard(wires=wire)

        # Oracle: flip the phase of |00>.
        for wire in range(2):
            qml.PauliX(wires=wire)
        qml.CZ(wires=[0, 1])
        for wire in range(2):
            qml.PauliX(wires=wire)

        # Grover diffusion operator (up to a global phase).
        for wire in range(2):
            qml.Hadamard(wires=wire)
            qml.PauliX(wires=wire)
        qml.CZ(wires=[0, 1])
        for wire in range(2):
            qml.PauliX(wires=wire)
            qml.Hadamard(wires=wire)

        return qml.sample()

    return circuit()

