import pennylane as qml


def grover_3SAT():
    dev = qml.device("default.qubit", wires=3, shots=1000)

    clauses = (
        (1, 2, 3),
        (-1, 2, 3),
        (-1, -2, -3),
        (-1, -2, 3),
        (1, 2, -3),
        (-1, 2, -3),
    )

    oracle = []
    for state in range(8):
        bits = [(state >> (2 - i)) & 1 for i in range(3)]
        satisfies = all(
            any(
                bits[abs(literal) - 1] == (1 if literal > 0 else 0)
                for literal in clause
            )
            for clause in clauses
        )
        oracle.append(-1 if satisfies else 1)

    @qml.qnode(dev)
    def circuit():
        for wire in range(3):
            qml.Hadamard(wires=wire)

        qml.DiagonalQubitUnitary(oracle, wires=[0, 1, 2])
        qml.GroverOperator(wires=[0, 1, 2])

        return qml.sample()

    return circuit()

