def swaptest_zaxis(unknown_state):
    """Return 1000 SWAP-test samples comparing unknown_state with |0⟩."""
    preparation = qml.tape.make_qscript(unknown_state.func)()
    wire_map = {wire: 1 for wire in preparation.wires}
    dev = qml.device("default.qubit", wires=3, shots=1000)

    @qml.qnode(dev)
    def circuit():
        for operation in preparation.operations:
            qml.apply(operation.map_wires(wire_map))

        qml.Hadamard(wires=0)
        qml.CSWAP(wires=[0, 1, 2])
        qml.Hadamard(wires=0)
        return qml.sample(wires=0)

    return circuit()

