import pennylane as qml
import numpy as np
from scipy.linalg import expm
import math


def HHL_4x4():
    A = 0.5 * np.array([
        [3, 0, 0, -1],
        [0, 7, -1, 0],
        [0, -1, 7, 0],
        [-1, 0, 0, 3],
    ], dtype=float)

    b = np.array([1 / math.sqrt(2), 1 / math.sqrt(2), 0, 0])
    t = math.pi / 4

    system = [0, 1]
    clock = [2, 3, 4]
    ancilla = 5

    U = expm(1j * A * t)
    dev = qml.device("default.qubit", wires=6, shots=1000)

    def phase_estimation():
        for wire in clock:
            qml.Hadamard(wires=wire)

        for index, wire in enumerate(clock):
            power = 2 ** (len(clock) - 1 - index)
            qml.ctrl(qml.QubitUnitary, control=wire)(
                np.linalg.matrix_power(U, power), wires=system
            )

        qml.adjoint(qml.QFT)(wires=clock)

    @qml.qnode(dev)
    def circuit():
        qml.StatePrep(b, wires=system)
        phase_estimation()

        for eigenvalue in range(1, 5):
            control_bits = [
                (eigenvalue >> shift) & 1
                for shift in (2, 1, 0)
            ]
            qml.ctrl(
                qml.RY,
                control=clock,
                control_values=control_bits,
            )(
                2 * math.asin(1 / eigenvalue),
                wires=ancilla,
            )

        qml.adjoint(phase_estimation)()
        return qml.sample()

    return circuit()

