def QSub():
    """
    Subtract b = 011 from a = 111 and return 1000 samples
    of the three result qubits, ordered most significant first.
    """
    dev = qml.device("default.qubit", wires=6, shots=1000)

    @qml.qnode(dev)
    def circuit():
        # Registers use least-significant-bit-first ordering.
        for wire in (0, 1, 2):  # a = 111
            qml.PauliX(wires=wire)
        for wire in (3, 4):     # b = 011
            qml.PauliX(wires=wire)

        # Controlled subtraction of each bit's value modulo 8.
        for i in range(3):
            for j in range(i, 3):
                qml.MultiControlledX(
                    wires=[3 + i] + list(range(i, j)) + [j]
                )

        return qml.sample(wires=[2, 1, 0])

    return circuit()

