import numpy as np


def qpe_grover00_gate(n_count=3):
    dev = qml.device("default.qubit", wires=n_count + 2, shots=1000)
    counting_wires = list(range(n_count))
    target_wires = [n_count, n_count + 1]

    oracle = np.diag([-1.0, 1.0, 1.0, 1.0])
    diffusion = np.eye(4) - np.ones((4, 4)) / 2
    grover = diffusion @ oracle

    @qml.qnode(dev)
    def circuit():
        for wire in counting_wires + target_wires:
            qml.Hadamard(wires=wire)

        for index, control in enumerate(counting_wires):
            unitary = np.linalg.matrix_power(grover, 2**index)
            qml.ctrl(qml.QubitUnitary, control=control)(
                unitary, wires=target_wires
            )

        qml.adjoint(qml.QFT)(wires=counting_wires)
        return qml.sample(wires=counting_wires)

    return circuit()

