from numpy import pi

dev = qml.device("default.qubit", wires=2, shots=1000)

@qml.qnode(dev)
def chsh_circuit(alice=None, bob=None):
    """Return 1000 samples of Alice's and Bob's CHSH outcomes."""
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])

    if alice == 1:
        qml.RY(pi / 2, wires=0)

    if bob == 0:
