def period_finding_7_15():
    """
    Find the period of a = 7 modulo N = 15 using 1000 shots.
    """
    counting_wires = list(range(4))
    work_wires = list(range(4, 8))
    dev = qml.device("default.qubit", wires=8, shots=1000)

    U = np.zeros((16, 16), dtype=complex)
    for x in range(16):
        U[(7 * x) % 15 if x < 15 else x, x] = 1

    @qml.qnode(dev)
    def circuit():
        for wire in counting_wires:
            qml.Hadamard(wires=wire)

        qml.PauliX(wires=work_wires[-1])

        for i, wire in enumerate(counting_wires):
            power = 2 ** (len(counting_wires) - 1 - i)
            qml.ControlledQubitUnitary(
                np.linalg.matrix_power(U, power),
                wires=[wire] + work_wires,
            )

        qml.adjoint(qml.QFT)(wires=counting_wires)
        return qml.sample(wires=counting_wires)

    return circuit()

