def shor_7mod15():
    """
    Run order finding for 7 modulo 15 using 8 phase qubits and
    4 work qubits. Return 1000 samples of the phase register.
    """
    phase_wires = list(range(8))
    work_wires = list(range(8, 12))
    dev = qml.device("default.qubit", wires=12, shots=1000)

    @qml.qnode(dev)
