import numpy as np

def ipe_t_gate():
    """
    Estimate the T gate phase using 3 IPE iterations.
    Return 1000 samples with bits ordered most significant first.
    """
    dev = qml.device("default.qubit", wires=2, shots=1000)

    @qml.qnode(dev)
    def circuit():
        qml.PauliX(wires=1)
        bits = []

        for iteration in range(3):
            qml.Hadamard(wires=0)

            for _ in range(2 ** (2 - iteration)):
                qml.ctrl(qml.T, control=0)(wires=1)

            for j, bit in enumerate(bits):
                qml.cond(bit, qml.PhaseShift)(
                    -np.pi / 2 ** (iteration - j), wires=0
                )

            qml.Hadamard(wires=0)
            bits.append(qml.measure(0, reset=True))

        return qml.sample(bits[::-1])

    return circuit()

