def VQE_Z2(param):
    """Optimize H = Z ⊗ Z and return 1000 computational-basis samples."""
    energy_dev = qml.device("default.qubit", wires=2, shots=None)
    sample_dev = qml.device("default.qubit", wires=2, shots=1000)

    angles = np.asarray(param, dtype=float).reshape(-1)
    if angles.size < 2:
        angles = np.pad(angles, (0, 2 - angles.size))

    hamiltonian = qml.Hamiltonian(
        [1.0], [qml.PauliZ(0) @ qml.PauliZ(1)]
    )

    def ansatz(theta):
        for i, angle in enumerate(theta):
            qml.RY(angle, wires=i % 2)
        qml.CNOT(wires=[0, 1])

    @qml.qnode(energy_dev)
    def energy(theta):
        ansatz(theta)
        return qml.expval(hamiltonian)

    result = minimize(
        lambda theta: float(energy(theta)),
        angles,
        method="Powell",
        options={"maxiter": 1000, "xtol": 1e-8, "ftol": 1e-10},
    )

    @qml.qnode(sample_dev)
    def circuit(theta):
        ansatz(theta)
        return qml.sample()

    return circuit(result.x)

