import numpy as np
from qiskit.circuit import QuantumCircuit
from qiskit.quantum_info import SparsePauliOp, Statevector
from scipy.optimize import minimize


def VQE_Z2(param):
    """Return an optimized, unmeasured VQE circuit for H = Z ⊗ Z."""
    hamiltonian = SparsePauliOp.from_list([("ZZ", 1.0)])

    initial = np.asarray(param, dtype=float).reshape(-1)
    if initial.size == 0:
        initial = np.zeros(2)
    elif initial.size == 1:
        initial = np.repeat(initial, 2)
    elif initial.size % 2:
        initial = np.append(initial, 0.0)

    def ansatz(theta):
        circuit = QuantumCircuit(2)
        for i in range(0, len(theta), 2):
            circuit.ry(float(theta[i]), 0)
            circuit.ry(float(theta[i + 1]), 1)
            circuit.cx(0, 1)
        return circuit

    def energy(theta):
        state = Statevector.from_instruction(ansatz(theta))
        return float(np.real(state.expectation_value(hamiltonian)))

    result = minimize(
        energy,
        initial,
        method="Powell",
        options={"xtol": 1e-8, "ftol": 1e-8, "maxiter": 1000},
    )
    return ansatz(result.x)
